import React, { useEffect, useState } from "react";
import styles from "./AboutStyles.module.css";
import axios from "axios";

function About() {
    const [profile, setProfile] = useState({
        summary: "",
        skills: [],
        education: []
    });

    useEffect(() => {
        axios.get("http://localhost:3001/latest-profile") 
            .then((response) => {
                setProfile(response.data);
            })
            .catch((error) => console.error("Error fetching Profile", error));
    }, []);

    return (
        <div className={styles.HomeContainer}>
            <h2 className={styles.header}>Professional Summary:</h2>
            <p>{profile.summary}</p>

            <h2 className={styles.header}>Skills:</h2>
            <ol className={styles.skill}>
                {profile.skills.map((skill, index) => (
                    <li key={index}>{skill}</li>
                ))}
            </ol>

            <h2 className={styles.header}>Education:</h2>
            <ul className={styles.education}>
                {profile.education.map((edu, index) => (
                    <li key={index}>
                        <strong>Degree:</strong> {edu.degree} <br />
                        <strong>Institution:</strong> {edu.institution} <br />
                        <strong>Mark/Percentage:</strong> {edu.marks} <br />
                        <strong>Pass-out Year:</strong> {edu.year} 
                    </li>
                ))}
            </ul>
        </div>
    );
}

export default About;
